/* RFC 6238 TOTP, SHA-1, 30 seconds, six digits. */
async function totp(secret: string, step: number) {
  const data = new Uint8Array(8);
  let counter = BigInt(step);
  for (let i = 7; i >= 0; i--) { data[i] = Number(counter & 255n); counter >>= 8n; }
